  assert(fs.existsSync(auditPath), 'audit.json written');

  const narrativeDoc = JSON.parse(fs.readFileSync(narrativePath, 'utf8'));
  const auditDoc = JSON.parse(fs.readFileSync(auditPath, 'utf8'));
  assert(typeof narrativeDoc.overview === 'string', 'narrative.json overview string');
  assert(typeof auditDoc.ticket === 'string', 'audit.json ticket string');

  assert(hasZh(narrative.overview), 'overview is Chinese');
  assert(
    /相对基线判定|跨态发现|因果推理/.test(narrative.overview),
    'overview contains WT-020 Chinese keywords'
  );

  assert(
    Array.isArray(narrative.topConclusions) && narrative.topConclusions.length >= 3,
    `topConclusions >= 3 (got ${narrative.topConclusions.length})`
  );
  assert(
    narrative.topConclusions.every((c) => hasZh(c.contribution)),
    'each topConclusion contribution is Chinese'
  );

  assert(
    Array.isArray(narrative.findings) && narrative.findings.length >= 10,
    `findings >= 10 (got ${narrative.findings.length})`
  );
  assert(
    narrative.findings.every((f) => typeof f.claim === 'string' && f.claim.length > 0),
    'each finding has claim'
  );
  const findingsWithKind = narrative.findings.filter((f) => typeof f.kind === 'string');
  assert(findingsWithKind.length >= 10, `findings with kind >= 10 (got ${findingsWithKind.length})`);
  const withRb = narrative.findings.filter((f) => f.relativeBaseline != null);
  assert(withRb.length >= 5, `findings with relativeBaseline >= 5 (got ${withRb.length})`);
  const withCausal = narrative.findings.filter((f) => f.causalChain != null);
  assert(withCausal.length >= 1, `findings with causalChain >= 1 (got ${withCausal.length})`);

  assert(
    Array.isArray(narrative.roiOptimizations) && (narrative.roiOptimizations?.length ?? 0) >= 3,
    `roiOptimizations >= 3 (got ${narrative.roiOptimizations?.length ?? 0})`
  );
  assert(
    (narrative.roiOptimizations ?? []).every(
      (r) =>
        hasZh(r.direction) &&
        hasZh(r.rationale) &&
        Array.isArray(r.findingIds) &&
        r.findingIds.length > 0
    ),
    'each ROI has Chinese direction+rationale and findingIds'
  );

  assert(typeof narrative.triadTrend === 'string' && narrative.triadTrend.length > 0, 'triadTrend present');
  assert(
    typeof narrative.topBusinessHotspot === 'string' && narrative.topBusinessHotspot.length > 0,
    'topBusinessHotspot present'
  );
  assert(
    typeof narrative.gpuBoundJudgment === 'string' && narrative.gpuBoundJudgment.length > 0,
    'gpuBoundJudgment present'
  );
  assert(
    typeof narrative.freqMorphologyJudgment === 'string' && narrative.freqMorphologyJudgment.length > 0,
    'freqMorphologyJudgment present'
  );

  assert(hasZh(html) && html.includes('ROI 优化方向'), 'report.html has Chinese + ROI section');
  assert(html.includes('业务红线') || html.includes('GPU-bound'), 'report.html has kind-driven sections');
}

// ─────────────────────────── Summary ───────────────────────────────

