    'gpuBoundJudgment present'
  );
  assert(
    typeof narrative.freqMorphologyJudgment === 'string' && narrative.freqMorphologyJudgment.length > 0,
    'freqMorphologyJudgment present'
  );

  assert(hasZh(html) && html.includes('ROI 优化方向'), 'report.html has Chinese + ROI section');
  assert(html.includes('业务红线') || html.includes('GPU-bound'), 'report.html has kind-driven sections');
}

// ─────────────────────────── Summary ───────────────────────────────

db.close();

console.log(`\n${'─'.repeat(50)}`);
console.log(`Results: ${passCount} PASS, ${failCount} FAIL`);
if (failCount > 0) {
  console.log('OVERALL: FAIL');
  process.exit(1);
} else {
  console.log('OVERALL: PASS');
  process.exit(0);
}

